/* 第0课：目标检测史。年份按首次公开时间排列，会议年份另标。 */
(()=>{
 const catalog=typeof lessons!=='undefined'?lessons:window.lessons, curriculum=window.visionlabYoloCurriculum;
 if(!catalog||!curriculum)return;
 const ref=(label,url)=>({label,url}), refs={
 early:ref('Rowley 等：Neural Network-Based Face Detection，1998','https://publications.ri.cmu.edu/neural-network-based-face-detection-3'),
 viola:ref('Viola–Jones，CVPR 2001','https://www.cs.utexas.edu/~grauman/courses/spring2007/395T/papers/viola_cvpr2001.pdf'),
 hog:ref('Dalal–Triggs：HOG，CVPR 2005','https://lear.inrialpes.fr/people/triggs/pubs/Dalal-cvpr05.pdf'),
 dpm:ref('Felzenszwalb 等：DPM，TPAMI 2010','https://pubmed.ncbi.nlm.nih.gov/20634557/'),
 voc:ref('PASCAL VOC 官方历史与任务说明','https://www.robots.ox.ac.uk/~vgg/projects/pascal/VOC/'),
 alex:ref('AlexNet，NeurIPS 2012','https://papers.nips.cc/paper/4824-imagenet-classification-with-deep-convolutional-neural-networks'),
 rcnn:ref('R-CNN，2013预印本／CVPR 2014','https://arxiv.org/abs/1311.2524'),
 over:ref('OverFeat，2013预印本／ICLR 2014','https://arxiv.org/abs/1312.6229'),
 spp:ref('SPP-net，2014预印本／ECCV 2014','https://arxiv.org/abs/1406.4729'),
 coco:ref('COCO 数据集，ECCV 2014','https://arxiv.org/abs/1405.0312'),
 fast:ref('Fast R-CNN，ICCV 2015','https://arxiv.org/abs/1504.08083'),
 faster:ref('Faster R-CNN，NeurIPS 2015','https://arxiv.org/abs/1506.01497'),
 yolo:ref('YOLO，2015预印本／CVPR 2016','https://arxiv.org/abs/1506.02640'),
 ssd:ref('SSD，2015预印本／ECCV 2016','https://arxiv.org/abs/1512.02325'),
 fpn:ref('FPN，2016预印本／CVPR 2017','https://arxiv.org/abs/1612.03144'),
 v2:ref('YOLO9000／YOLOv2，2016预印本／CVPR 2017','https://arxiv.org/abs/1612.08242'),
 focal:ref('RetinaNet 与 Focal Loss，ICCV 2017','https://arxiv.org/abs/1708.02002'),
 v3:ref('YOLOv3 技术报告，2018','https://arxiv.org/abs/1804.02767'),
 fcos:ref('FCOS，ICCV 2019','https://arxiv.org/abs/1904.01355'),
 v4:ref('YOLOv4，2020','https://arxiv.org/abs/2004.10934'),
 v5:ref('YOLOv5 官方初始版本记录','https://github.com/ultralytics/yolov5/releases/tag/v1.0'),
 detr:ref('DETR，ECCV 2020','https://arxiv.org/abs/2005.12872'),
 deform:ref('Deformable DETR，2020预印本／ICLR 2021','https://arxiv.org/abs/2010.04159'),
 yolox:ref('YOLOX，2021','https://arxiv.org/abs/2107.08430'),
 grounding:ref('Grounding DINO，2023预印本／ECCV 2024','https://arxiv.org/abs/2303.05499'),
 rt:ref('RT-DETR，2023预印本／CVPR 2024','https://arxiv.org/abs/2304.08069'),
 v10:ref('YOLOv10，NeurIPS 2024','https://arxiv.org/abs/2405.14458')};
 const parts=[];
 function section(id,title,paragraphs,keys,flow,q,options,answer,why){parts.push({id:'history-'+id,title:`${parts.length+1}. ${title}`,paragraphs,historyRefs:keys.map(k=>refs[k]),historyFlow:flow,subheadings:{},legacyIndex:800+parts.length,exercise:{q,options,answer,why}});}
 section('start','故事的起点：计算机怎样在整张图里找东西',[
  '把一张路口照片交给计算机，要求找出每辆车和每个行人。答案需要包含类别、位置和分数；照片里有几个对象，答案就可能有几条。分类只回答整张图片属于什么类别，检测还要逐个定位。后面所有方法都在处理这几个问题：去哪里找，怎样认，怎样画准框，以及怎样在有限时间内完成。',
  '困难来自变化：同一辆车远近不同，像素大小就不同；换角度后形状改变，遮挡会使一部分消失，广告牌又可能与车辆局部相似。早期可从模板、边缘或几何规则入手，但固定模板很难覆盖这些变化。于是研究者让程序在许多位置和尺度检查局部区域，并从带标注的例子中学习判断规则。',
  '滑动窗口就是把一个矩形观察区域依次移到各个位置。教学算例：640×480 图片，窗口64×64，水平和垂直步长都为32，只取完全落在图内的位置，共有19×14=266个窗口。再换窗口大小或缩放图片，检查数继续增加。如何少算、快算、共享计算，成为长期问题。',
  '1998年 Rowley、Baluja 和 Kanade 的正面人脸检测系统已让神经网络检查小窗口，并把误检的非人脸加入训练。困难负样本就是那些容易骗过模型的背景。神经网络用于检测早于2012年；后来改变的是可学习特征的能力、数据规模、训练方式与计算条件。'
 ],['early'],['整张图','多个位置／尺度的窗口','判断各窗口','合并重复结果'],'一个图片分类器给出“有车”，已经完成目标检测了吗？',['完成了','还要分别给出每辆车的位置','只需提高分类分数'],1,'检测需要逐实例的位置与类别，输出数量可随图片变化。');
 section('cascade','2001：Viola–Jones，把大部分背景尽早排除',[
  '如果每个窗口都做复杂计算，实时人脸检测很难运行。Viola 和 Jones 的办法是先用便宜的判断排掉明显背景，把更多计算留给少量像人脸的窗口。这是级联分类器：窗口必须依次通过多个检查，某一级否决后就停止处理。',
  '它用矩形区域的亮度差作为特征，例如比较相邻明暗区域；积分图让矩形像素和能快速计算。AdaBoost 从很多候选特征中选择有用的简单判断并组合成分类器。特征、快速求和、级联筛除共同构成检测流程，不能只把贡献归结为一个公式。',
  '用一个纯教学数字理解节省的计算：1000个窗口先过简单一级，若只剩100个，复杂一级就只处理这100个。真实系统各级保留比例由训练和阈值决定。早期否决太激进也会漏掉人脸，因此速度与漏检必须一起考虑。',
  '这项工作代表了实用人脸检测的重要进展，但主要针对特定目标及姿态设定。接下来面对街上姿态多变的行人，研究者还需要更能描述外形变化的特征。'
 ],['viola'],['矩形亮度特征','积分图快速计算','简单一级筛背景','后续级联细查'],'级联为什么能减少计算？',['所有窗口只看一次像素','明显背景提前退出，后续只处理少量窗口','把训练样本全部删除'],1,'较复杂的后续判断只花在通过前面检查的窗口上。');
 section('features','2005—2010：HOG 与 DPM，先教程序看轮廓和部件',[
  '2005年 Dalal 和 Triggs 用 HOG 描述行人的局部轮廓。梯度表示像素值朝哪个方向变化、变化多强；在小区域统计这些方向，再对相邻区域做归一化，可以得到比原始亮度更稳健的外形描述。线性 SVM 则学习哪些描述更像行人。',
  '2005年启动的 PASCAL VOC 挑战推动了共同评价：不同研究者在规定的训练、测试数据和任务上比较方法。VOC2007 扩展到20类，检测从单一人脸或行人进一步面向多种日常对象。统一数据集让进展更容易比较，也暴露出姿态、背景和遮挡问题。',
  'DPM 系列在2008年前后发展，2010年的期刊论文系统介绍了可变形部件模型。它把对象表示为整体模板和若干部件，部件允许在一定范围内移动，同时对不合理的位移施加代价。例如人的身体轮廓相近，手脚位置却会随姿态变化。',
  '这一路线已经会从数据学习分类器和部件参数，但基础描述仍主要依赖人工设计的特征。增加类别和复杂外观时，设计与组合特征越来越费力。下一次转折是：让特征提取本身也从大规模数据中学习。'
 ],['hog','voc','dpm'],['窗口／图像金字塔','HOG外形描述','整体与部件评分','筛选目标位置'],'DPM 想缓解什么问题？',['所有目标永远是刚性正面形状','同类目标的部件位置随姿态变化','图片必须只有一种颜色'],1,'部件的可变形布局帮助表示同类对象的姿态变化。');
 section('alex','2012：AlexNet 带来的转折，学习特征成为主线',[
  'AlexNet 在 ImageNet 图像分类上的结果显示，深卷积网络结合大规模标注、GPU训练等条件，可以学习有用的视觉特征。卷积层不再由人逐项规定“车应该有哪几种边缘”，而是通过训练调整数值，使特征有利于目标任务。',
  '但分类网络通常输出整张图的类别分数，检测需要许多对象的位置。研究者因此面对新问题：怎样让强大的分类特征服务于不同位置的目标？可以先找可能含对象的区域，把它们送入网络；也可以在图像上密集共享卷积计算。这两种思路随后同时发展。',
  '预训练与微调在这里成为关键工具：先在大型分类数据集学习参数，再用检测数据继续训练。前一阶段提供较好的特征起点，后一阶段适配检测目标。这个过程解释了后续为什么常用预训练权重，也说明检测性能还依赖数据、定位和训练设计。'
 ],['alex','rcnn'],['大量标注与GPU训练','CNN学习视觉特征','分类特征迁移到检测'],'分类网络为何不能直接给出整图里每辆车的框？',['分类输出通常没有逐对象的位置列表','卷积不能处理图片','分类完全不需要学习'],0,'分类与检测的输出要求不同，需要增加区域或密集定位机制。');
 section('rcnn','2013—2014：R-CNN 与 OverFeat，两种深度检测思路出现',[
  '2013年11月公开、2014年发表于CVPR的 R-CNN，把外部区域建议与 CNN 结合。区域建议先给出可能含目标的矩形，例如 Selective Search 根据图像线索生成一批区域；每个区域裁剪、变换后经过网络，再分类并修正边界框。',
  '这样做充分利用了深度特征，但许多候选区域互相重叠，逐区域运行卷积会反复处理相同像素，训练也包含多个步骤。改进问题由“特征够不够强”进一步变成“能不能共享这部分重复计算”。',
  '2013年12月公开的 OverFeat 则展示了在卷积网络中高效实现多尺度滑窗，并结合分类与定位。历史并非所有人先做完区域方法，之后才开始密集方法；多种路线同时探索怎样把整图特征转为对象位置。'
 ],['rcnn','over'],['R-CNN：区域建议','逐区域CNN','分类与框修正'],'R-CNN 的主要重复计算来自哪里？',['许多重叠候选各自运行卷积','只计算一次IoU','每张图只看一个区域'],0,'重叠区域大量共享像素，却分别提取卷积特征。');
 section('spp','2014：SPP-net 与 COCO，共享特征，也走向复杂场景',[
  'SPP-net 把卷积计算移到整张图上，再从共享特征中取候选区域。空间金字塔池化把不同大小的区域汇总成固定长度表示，使后面的全连接层能够接收它们。卷积特征可以复用，候选仍需逐区域处理。',
  '同年提出的 COCO 将更多日常对象放在复杂自然场景中：多个对象、尺度变化和上下文成为评价重点。数据集的发展与算法的发展相互推动；只在干净、单目标图片上表现好，已经无法说明复杂场景中的检测能力。',
  '读历史结果时必须看评价条件。VOC 与 COCO 的任务、数据和指标设置不同；AP50 与多IoU阈值平均的AP也回答不同问题。不同论文中的一个百分比，只有数据划分、输入和评价协议等条件一致时才适合直接比较。'
 ],['spp','coco'],['整图卷积一次','区域映射到共享特征','池化为固定长度','区域判断'],'SPP-net 的共享计算主要发生在哪一部分？',['整图卷积特征提取','为所有目标写同一个类别','删除区域位置'],0,'它复用整图卷积，后续区域汇总与分类仍有各自计算。');
 section('2015','2015：Fast、Faster 与 YOLO，速度问题催生不同答案',[
  '2015年4月公开的 Fast R-CNN 在整图共享特征上使用 RoI Pooling，把候选区域汇总成固定大小，并在同一训练框架中学习分类与框回归。回归就是预测位置等连续数值。区域建议仍来自外部流程，逐渐成为速度瓶颈。',
  '同年6月公开的 Faster R-CNN 用区域建议网络 RPN 产生候选，并与区域检测头共享卷积特征。Anchor 是放在特征位置上的参考宽高；RPN 据此预测目标性和框调整，再将候选交给区域检测头进一步分类和修框。',
  '几乎同一时期公开的 YOLO 从整图直接输出网格化的框和类别相关数值。它走向一阶段密集预测：许多位置直接作答，后续再筛选。原论文在2015年公开，会议发表是CVPR 2016，两个年份指不同事件。',
  '两阶段与一阶段描述预测职责的组织。前者先建议区域，再做区域级检测；后者直接从特征产生密集检测预测。两者都可能有很多卷积层、多个尺度和后处理。速度优势也必须结合具体模型、硬件与输入测量。'
 ],['fast','faster','yolo'],['Fast：共享特征＋外部候选','Faster：RPN＋区域头','YOLO：直接密集预测'],'为何“一阶段”仍可以有 NMS？',['阶段说的是检测职责，NMS属于结果筛选','NMS能让任何模型变成两阶段','一阶段一定只有一层'],0,'结果去重与针对候选区域再做分类精修是不同操作。');
 section('ssd','2015—2016：SSD，让不同大小的特征图一起预测',[
  '2015年12月公开、2016年发表于ECCV的 SSD 直接在多张特征图上预测。空间位置较多的图提供较密的预测机会，较粗的图配合较大范围特征；每个位置放若干不同形状的默认框，网络预测类别与位置偏移。',
  '默认框与 Anchor 都提供参考几何形状，具体匹配、偏移与类别定义由方法决定。SSD300 的经典配置有六张预测特征图，共8732个默认框；这表示筛选前候选的数量，最终物体数量随图片内容改变。',
  '密集预测带来新的训练问题：绝大多数位置是背景。SSD 用难负样本挖掘，从背景中挑选较难判断的样本参与训练。多尺度、参考框、前景背景不平衡，从此成为理解检测器的重要线索。'
 ],['ssd'],['多尺度特征','默认框与偏移','类别预测','汇总与NMS'],'8732个默认框是否表示图中有8732个物体？',['是','是固定候选数量，后续要筛选','是类别数'],1,'默认框为预测提供参考，不能直接当作最终对象。');
 section('pyramid','2016—2017：FPN、YOLOv2 与 RetinaNet，处理尺度和背景',[
  '2016年12月公开的 FPN 提出自上而下路径和横向连接，把深层特征与较高分辨率特征组合，让多个尺度都获得较强的语义表达。语义在这里指有助于识别类别和对象结构的特征信息。FPN 是特征组织方法，既可用于两阶段，也可用于一阶段检测器。',
  '同月公开的 YOLO9000 论文介绍 YOLOv2，采用参考框、训练框形状聚类和多尺度训练等改进。聚类是根据标注宽高寻找代表性形状；多尺度训练则让模型适应不同输入尺寸。这里的训练输入变化，与同时在多张特征图上预测是两个不同概念。',
  '2017年的 RetinaNet 使用 FPN 做密集预测，并提出 Focal Loss。它降低已容易正确分类样本的损失权重，把更多训练影响留给难例。海量简单背景不再轻易淹没少量前景，说明检测精度提升也可以来自训练目标，而不只来自加深网络。'
 ],['fpn','v2','focal'],['尺度问题 → 融合特征','参考尺寸 → 数据适配','大量易背景 → 调整损失'],'FPN 主要改变哪一部分？',['多尺度特征的表达与融合','标签的类别名称','图片文件扩展名'],0,'FPN 组织特征，不能由它单独决定检测阶段或标签规则。');
 section('free','2018—2019：YOLOv3 与 FCOS，继续探索密集预测的表示',[
  '2018年的 YOLOv3 结合更强的 Darknet-53 特征提取与三个尺度的预测。若输入为416×416，常见预测网格为13×13、26×26和52×52。多个尺度增加不同大小目标的预测机会，但具体输出仍依赖该版本的框表示和训练设计。',
  '2019年的 FCOS 使用特征位置直接预测到目标框四边的距离，并加入中心度等设计。它属于 Anchor-free 路线：不需要事先列出若干参考宽高，但仍必须决定哪些位置监督哪个真实框，以及如何处理重叠目标。',
  '用一个简化坐标例子理解：特征位置对应原图点(100,80)，预测到左、上、右、下的距离分别为(20,10,30,40)，框就是左上(80,70)、右下(130,120)。真正模型还需结合步长、尺度和训练分配。去掉参考框改的是几何表示的一部分，不会自动取消NMS。'
 ],['v3','fcos'],['有参考宽高的预测','或位置到四边距离','训练分配与损失','候选筛选'],'Anchor-free 是否意味着无需目标分配？',['是','仍需确定哪些位置学习哪些目标','只适合分类'],1,'预测表示与训练监督分配是相关但不同的设计。');
 section('2020','2020：YOLOv4、YOLOv5，把精度、训练和部署放到一起',[
  '2020年4月公开的 YOLOv4 研究结构和训练技巧的组合：CSP连接、特征融合、Mosaic 等增强以及定位损失等共同影响效果。工程上的问题是如何在可用硬件和训练成本内，取得适合实际应用的速度与精度。',
  '同年出现的 Ultralytics YOLOv5 是基于 PyTorch 的项目与模型系列，提供数据读取、训练、验证、推理和导出等工程流程。YOLOv4 与 YOLOv5 来自不同团队和代码实现，版本数字不能当作同一作者连续写出的单条代码血缘。',
  '本网站后续固定研究 YOLOv5 v7.0 的标准 Anchor 检测模型：Backbone 提取特征，Neck 融合尺度，Detect 输出候选，再经筛选和坐标还原得到框。早期版本与v7.0在模块上也有变化，所以学习时要同时记录仓库、版本、模型配置和输入尺寸。'
 ],['v4','v5'],['网络结构','数据与训练策略','评价与导出','可复现的工程流程'],'看到“YOLOv5”名称就能确定每层结构吗？',['能','还需仓库版本、配置和输入条件','只看年份即可'],1,'项目会演进，结构和输出必须落回具体配置与源码。');
 section('detr','2020：DETR，把重复候选问题写进训练目标',[
  '2020年5月公开的 DETR 把检测看作一个对象集合的预测。它仍先从图片提特征，再用 Transformer 编码与解码处理全图关系；一组可学习的对象查询产生一组候选答案，每个查询不是一个预设类别。',
  '训练时，二分图匹配在预测集合与真实对象之间寻找一对一配对。匹配后的预测学习类别与框，没有对象可配的查询学习“无对象”。这样把重复预测的约束放进训练，标准 DETR 推理不依靠传统 NMS 去重。',
  '例如图中有3个目标，而网络有100个查询，训练会选出与这3个目标配对的预测，其余学习无对象；不是要求每张图有100个物体。原始 DETR 仍有收敛较慢、小目标处理较弱等挑战，Transformer 也没有消除图像分辨率与计算预算的问题。'
 ],['detr'],['图像特征＋对象查询','预测集合','一对一匹配训练','直接输出对象集合'],'DETR 的100个查询是否对应100个固定类别？',['是','查询是预测槽位，训练中还可学习无对象','查询就是100张图片'],1,'查询产生对象候选，类别由预测头输出。');
 section('2021','2020—2021：Deformable DETR 与 YOLOX，各自补上短板',[
  '2020年10月公开、2021年发表于ICLR的 Deformable DETR，让注意力围绕参考位置选取少量采样点，并利用多尺度特征。它减少处理高分辨率特征时的负担，改善训练收敛和小目标表现。这里的参考位置与预先列举一组Anchor宽高不是同一概念。',
  '2021年的 YOLOX 将 Anchor-free、分类定位解耦头和 SimOTA 目标分配结合。解耦头为分类与定位安排不同分支；动态分配则根据训练中的预测与代价安排监督。这表明实时密集检测同样持续优化“怎样表示、谁来负责、怎样学习”。',
  '从这一阶段开始，理解新方法更适合按设计问题拆解：特征从哪里来，框如何参数化，标签怎样匹配，损失优化什么，推理还要哪些后处理。一个新名称常包含多项组合，不能只记住某个模块就推断全部实现。'
 ],['deform','yolox'],['DETR路线：高效注意力','密集路线：解耦与分配','共同检查：计算与监督'],'分类和定位解耦主要表示什么？',['安排不同预测分支处理两类任务','训练与推理使用完全无关图片','把类别标签删除'],0,'分支设计改变任务特征的组织，输出与损失仍需配套。');
 section('2023','2023：语言提示和实时集合检测，拓展两个方向',[
  '2023年3月公开、2024年发表于ECCV的 Grounding DINO，将语言与视觉特征结合。用户可以给出类别名称或描述性短语，模型寻找与文字对应的区域。开放词汇能力让检测从固定类别表走向文本条件查询，但能否识别某个对象仍受预训练覆盖、表达和图像条件影响。',
  '例如输入“红色的汽车”，模型要同时理解对象类别与属性，再给出相关框；这与只在固定的“人、车、狗”编号里分类不同。文字可能含糊，图像可能遮挡，因此新类别和新场景依然需要评价，文本输入本身不是识别正确的保证。',
  '同年4月公开、2024年发表于CVPR的 RT-DETR，则针对实时性改进 DETR 路线，设计高效特征编码与查询选择，关注包括后处理在内的运行开销。实时密集检测与集合预测的研究开始在工程速度目标上更直接地比较。'
 ],['grounding','rt'],['文本＋图像 → 条件检测','高效集合预测 → 实时目标','各自按数据与硬件评价'],'开放词汇检测增加了哪种输入方式？',['文字类别或对象描述','必须把每张图人工裁成目标','无需图片'],0,'文字可提供检测条件，模型仍要从图像中定位相关区域。');
 section('2024','2024：YOLOv10，实时密集路线也探索免 NMS',[
  '2024年5月公开的 YOLOv10 通过一致的双重分配等训练设计，探索免NMS的实时检测，并从结构效率上减少冗余。它说明是否使用NMS与是否使用Transformer并不是同一条分类轴：卷积实时检测路线同样可以重新设计训练匹配和推理输出。',
  '截至这里，已经可以看到多条并行路线：传统区域检测不断改进特征和区域头；密集预测改进表示、分配、损失与效率；集合预测改进收敛和计算；语言条件检测拓展类别表达。年代较新代表提出了新的设计组合，不意味着任何场景都能直接替换旧模型。',
  '学习历史的目的，是获得阅读方法的能力。遇到后续的新模型，先找它具体解决哪一处瓶颈，再检查原论文、代码版本和实验条件。这里选取的节点覆盖关键范式转折；持续更新的产品版本与完整排行榜应回到官方项目核对。'
 ],['v10'],['训练分配设计','结构效率设计','免NMS的推理路径'],'免NMS是否只可能由Transformer实现？',['是','不同模型路线都可通过匹配与输出设计探索','只要删掉NMS调用就行'],1,'免NMS通常需要训练和输出设计配合，不能只删除后处理。');
 section('connect','读完历史，再回到你要训练的检测器',[
  '现在再看一张道路图片，可以把整个系统拆成明确的工作：预处理决定像素怎样进入模型；特征提取表示图像线索；特征融合整理不同尺度；预测头写出候选；训练分配与损失告诉模型怎样改进；推理整理输出，评价检验效果。每个环节都能找到历史上的问题来源。',
  '后面先学检测任务和两类流程，再认识 YOLOv5 的整机、仓库与数据。进入C3、SPPF和Detect时，带着“这个模块收到什么、解决什么、交出什么”阅读。若准备改进模型，也应先从失败图片判断瓶颈属于特征、监督、数据还是后处理。',
  '本课时间线按论文首次公开年份排列，预印本和会议年份同时标注；同年方法并不代表互相直接继承。文中的窗口数、级联保留数和坐标是教学计算，不是不同论文间的性能比较。每节附原始资料，读到感兴趣的路线可以继续查原文和后续专题。'
 ],['rcnn','yolo','detr'],['历史问题','当前模块职责','具体失败证据','有依据的改进实验'],'读完历史后，改进模型最合理的起点是什么？',['先盲目堆叠最新模块','从失败证据定位瓶颈，再设计对照','只比较模型名字大小'],1,'方法需要针对问题，并通过一致协议评价它是否有效。');
 const l={id:'detection-history',group:'yolo',title:'第0课 · 目标检测发展史：从滑动窗口到语言提示',desc:'沿时间线追踪问题、方法与转折，理解目标检测怎样一步步发展成今天的多条技术路线。',time:75,level:'背景',sections:parts,yoloNumber:0,curriculumPhase:'background',curriculumIntro:'背景导读 · 先理解问题怎样推动方法变化，再进入第01课。',prereq:'从图片、矩形和简单四则运算开始；首次出现的技术名词会在正文解释。',prereqLinks:[],goals:['按年代解释检测方法的主要转折。','区分特征、搜索、预测表示、监督与后处理的改进。','把历史问题与后续YOLOv5模块联系起来。'],keypoints:['从“在哪里算”到“怎样共享计算”，搜索开销一直推动方法演进。','从人工特征到CNN、多尺度和集合预测，表示与训练共同改变。','阶段、Anchor、Transformer、NMS与词汇范围是不同设计维度。'],sources:Object.values(refs),quiz:parts[parts.length-1].exercise,chapterExercises:[parts[6].exercise,parts[11].exercise,parts[13].exercise],worked:{title:'用一张道路图回顾三种做法',prompt:'图里有3辆车，滑动窗口、密集预测与集合预测分别怎样产生候选？',solution:'滑窗在多个位置和尺度检查区域；密集预测在特征位置输出候选；集合预测用查询输出集合并以匹配组织训练。最终结果还要遵循各方法自己的输出与筛选约定。'}};
 // 用具体机制和可复算例子深化各历史节点；保留原年代主线。
 const deepen=(id,title,paragraphs,table)=>{const s=parts.find(p=>p.id==='history-'+id);const start=s.paragraphs.length;s.subheadings[start]=title;s.paragraphs.push(...paragraphs);if(table){s.historyTable=table;s.historyTableAt=start;}};
 deepen('start','把搜索空间算出来：位置、尺度与重复结果',[
  '为什么只扫描一种窗口不够？64×64窗口可能适合远处小车，却装不下近处大车。图像金字塔把原图缩放成多个尺寸，再使用同一个检测窗口扫描；映回原图后，相同窗口对应不同大小的区域。另一种做法是在原图改变窗口尺寸，两者都在覆盖尺度变化。',
  '一张640×480图片上，64×64窗口、步长32时，横向位置数是 floor((640−64)/32)+1=19，纵向是 floor((480−64)/32)+1=14。若把步长改为16，变成37×27=999个位置，检查次数接近原来的四倍；多个尺度还会继续增加开销。步长减小能检查得更密，也会产生更多相邻的相似窗口。',
  '同一辆车周围可能有许多窗口都得高分，检测器因此还需要把重复答案整理为对象列表。非极大值抑制 NMS 的常见流程是先保留最高分框，再删去与它重叠过大的同类框，重复处理余下候选。重叠用 IoU 衡量：交集面积除以并集面积。',
  '两个100×100的框仅水平错开10，交集为90×100=9000，并集为10000+10000−9000=11000，IoU约0.818。若同类别NMS阈值为0.5，低分框会被抑制；若它们其实属于两辆紧挨着的车，就可能误删。因此重复预测与拥挤场景一直影响后续方法设计。'
 ],{headers:['窗口设定','横向×纵向','位置数'],rows:[['64×64，步长32','19×14','266'],['64×64，步长16','37×27','999'],['增加图像尺度','每个尺度各算一次','总量继续累加'] ]});
 deepen('cascade','积分图和级联分别省下什么计算',[
  '一个矩形亮度特征可以是“左半区域像素和减右半区域像素和”。直接把每个窗口内的像素重新累加很费时。积分图在每个位置保存从左上角到该处的累计和，先用一次整图计算，之后任意矩形的像素和都能用四个累计值相加减得到。',
  '将矩形表示为四个边界位置 A、B、C、D，其中D是右下，A是左上边界之前的累计位置，矩形和为 D−B−C+A。例如右下累计50、上方累计20、左方累计10、左上补回5，矩形内的和就是25。它减少了求特征的成本；这些明暗特征是否有判别力，还需要用人脸和背景样本学习。',
  'AdaBoost 在许多简单特征判断中逐步选择并加权组合，训练时更关注前面难以分对的样本。级联再把不同复杂度的分类器排成一系列检查。积分图让一次检查更便宜，级联让大量窗口少做后续检查，二者解决不同部分的耗时。',
  '教学计算：第一级检查1000个窗口，每个成本1，留下100个；第二级每个成本10，总成本1000+100×10=2000。如果所有窗口都直接做第二级，成本为10000。但目标若在第一级就被错误拒绝，后面无法找回；级联需要在每级保留真实目标与快速排背景之间设定阈值。'
 ]);
 deepen('features','从像素到 HOG，再从整体模板到部件',[
  'HOG怎样把图片变成数字？先用相邻像素差近似水平和垂直梯度，再计算变化强度和方向。将小区域称为cell，把其中像素按方向投票到直方图；变化越强，票的权重通常越大。相邻cell组成block并进行归一化，减少整体明暗和对比度变化的影响。',
  '经典行人窗口的一种设置是64×128像素，cell为8×8，因此有8×16个cell；每个block包含2×2个cell，按一个cell步长滑动，可放7×15个block。每cell有9个方向箱，则描述长度是7×15×2×2×9=3780。HOG在这里给出了固定长度表示，SVM再学习这3780个数如何区分行人与背景。',
  'DPM进一步给整体和部件分别打分。可把总分理解为“整体模板分＋各部件外观分−部件位移代价”。两个候选的外观分都是9时，若不合理布局代价分别为1和4，总分便是8和5；模型更偏向外观合适、布局也合理的候选。真实DPM还要学习组件、部件与位置等参数。',
  '部件位置往往没有逐一人工标注，训练需要推断这些隐藏布局，再调整模型。这样可以解释“同一类别的姿态为什么还能变化”，但人工设计的底层特征仍限制了可表达的外观信息。CNN后来将特征学习纳入训练，使这个瓶颈发生变化。'
 ],{headers:['HOG组成','数量','含义'],rows:[['cell','8×16','每8×8像素一组'],['block位置','7×15','每次移动一个cell'],['最终描述','3780维','105个block，各36个数'] ]});
 deepen('alex','从学习分类器，到连特征提取一起学习',[
  '用HOG时，梯度方向怎样统计由人规定，训练主要调整后面的分类规则。CNN把卷积核也设为可训练参数：输出与标签的误差反向传递，改变前面提取线索的方式。浅层和深层逐步组合局部响应，使模型能为数据和任务学习更合适的表示。',
  '预训练能节省什么？检测标注需要画出每个对象的框，往往比整图分类标签贵。先用大量分类数据学习特征，再在检测数据上微调，可以利用已有参数作为起点。微调仍需用检测损失调整网络，预训练类别与目标检测类别也不必完全相同。',
  '特征能力增强后，定位难题仍然存在：一张图片的整体向量适合整图分类，却需要额外机制说明哪处特征属于哪辆车。接下来的区域方法保留空间位置、按区域读取特征；密集方法则在特征图多个位置同时输出，二者都要把“表示”变成“对象级答案”。'
 ]);
 deepen('rcnn','R-CNN 实际怎样训练、定位和复用特征',[
  'R-CNN先用 Selective Search 根据颜色、纹理、大小等区域相似性合并图像区域，并形成候选矩形。候选不需要已经知道是什么类别，只要尽量覆盖可能的对象；如果真实目标始终没有进入候选集合，再强的区域分类器也难以找回它。',
  '原始R-CNN把每个候选变换成固定输入尺寸后过CNN。网络先以分类预训练参数初始化，再用检测区域进行微调；之后为各类训练线性SVM，并训练边界框回归器。这些步骤分开进行，提取出的区域特征还会被存储供后续训练使用。',
  '边界框回归并非重新搜索整张图，而是根据候选特征预测中心与宽高的相对修正。假设候选中心为(50,40)、宽高(40,20)，目标中心为(60,45)、宽高(80,20)，归一化中心修正是(0.25,0.25)，对数宽高修正是(ln2,0)。这样把不同尺度的框转换到相对调整量上。',
  '一次原始R-CNN检测可能处理约两千个区域。数量在每张图并非严格固定；关键是相邻候选高度重叠，卷积仍被重复计算。OverFeat等整图卷积思路和随后共享特征的区域方法，都把减少重复作为重要方向。'
 ]);
 deepen('spp','共享特征怎样接住大小不同的区域',[
  '假设整图共享特征有256个通道，某个候选覆盖8×6个特征位置，另一个覆盖12×9。后面的全连接层需要固定长度输入，不能直接把不同数量的格子全部展开。空间金字塔池化把区域分别划成固定数量的网格，在每格每通道内汇总。',
  '若使用1×1、2×2、4×4三层金字塔，每通道共得到1+4+16=21个数，256个通道就是5376维。输入区域大一些或小一些，划分格数仍固定，因此结果长度一致；格子的实际覆盖范围则随区域改变。',
  '图像金字塔、空间金字塔池化和后来的特征金字塔不是同一操作：前者缩放原始图像；SPP把一个区域分成多种网格并汇总成表示；FPN在网络中融合不同分辨率特征。它们都与尺度有关，计算位置和输出用途却不同。',
  '数据集也决定模型被要求做好什么。IoU=0.5时合格的粗框，在0.75时可能不合格；小目标偏移几像素，IoU变化可能更明显。COCO常用AP在0.50至0.95、间隔0.05的十个阈值上平均，使定位精度进入评价，和只报告AP50相比更严格。'
 ]);
 deepen('2015','Fast/Faster 的区域计算，以及 YOLO 的直接输出',[
  'Fast R-CNN 的 RoI Pooling 将候选映射到共享特征，划成固定的网格，对每格做最大池化。以单通道4×4区域分成2×2格为例，每个格取自己的最大值，得到2×2输出；所有通道分别处理。边界划分有量化，区域坐标与特征格子之间并非连续精确采样。',
  'Fast R-CNN 的检测头同时输出类别分布和框回归；训练用分类损失和定位损失共同学习，背景区域只参与相应分类监督。整图卷积复用之后，外部候选建议成为明显的时间成本，这才有了将建议过程也放入共享网络的动机。',
  'Faster R-CNN 的经典RPN在每个位置安排k个Anchor，用分类分支判断目标／背景，用回归分支写出k组四维修正。例如40×30个位置、每处9个Anchor，共10800个参考候选。经过解码、过滤和NMS产生建议区域，再交给第二阶段检测头。',
  'RPN与最终检测头的监督职责不同：RPN主要学习候选是否含目标及其位置，最终头继续识别类别并精修。训练时根据Anchor与真实框的重叠等规则分配标签；真实框只用于训练和评价，新图推理不需要标注。',
  '初代YOLO的VOC设定则输出7×7×(2×5+20)=1470个数：每格两个框各有坐标和置信度，共享20个类别条件概率。某框置信度0.8、车的条件概率0.7，则该框车类别分数为0.56。两个框共享类别数限制了同格多目标的表达，后续版本重新组织了预测。'
 ]);
 deepen('ssd','SSD怎样在六张图上预测，又怎样分配正负样本',[
  '经典SSD300使用38×38、19×19、10×10、5×5、3×3、1×1六张预测图，每位置默认框数分别为4、6、6、6、4、4。总数为5776+2166+600+150+36+4=8732。网络在每个默认框上分别预测类别与偏移，不能把六层理解成逐对象处理的六个检测阶段。',
  'VOC的20类加背景一共21类。第一张图每位置4个默认框，分类卷积需写出4×21=84个通道，定位卷积写出4×4=16个通道。把空间位置和默认框维度展开后，才能获得8732条完整的候选记录。',
  '训练时，默认框与真实框匹配后，正样本学习真实类别和位置偏移，负样本学习背景。难负样本挖掘按背景分类损失选择较难样本，原论文将负正数量比控制到最多3:1；如果一张图匹配出20个正样本，最多选60个负样本。',
  '较高分辨率特征图有更多位置，却不自动保证小目标好检。小目标在输入中可能只剩几像素，早期特征表达较弱，增强和匹配也会改变可学习的样本。后面的FPN进一步处理“高分辨率与强语义怎样结合”的问题。'
 ]);
 deepen('pyramid','FPN怎样融合，Focal Loss怎样压低简单背景的影响',[
  '假设主干较粗特征是20×20、较细特征是40×40。FPN先用1×1卷积把横向分支的通道调整为约定值，把粗特征上采样到40×40，再与同尺寸的横向特征逐元素相加，之后再用卷积处理。相加要求空间和通道形状相容；它不同于YOLOv5 Neck里常见的通道Concat。',
  'FPN让较细的位置表达能结合更深层的信息。与把原图缩放多次、分别运行主干相比，利用已有分层特征更便于共享计算；但增加融合路径和高分辨率预测仍有内存与运行成本。',
  'Focal Loss 可以先从二分类读起。令 p_t 为模型分给真实答案的概率，普通交叉熵为 −ln(p_t)，调制后的形式为 \\(FL(p_t)=-\\alpha_t(1-p_t)^\\gamma\\ln p_t\\)。其中γ控制对容易样本的抑制程度，α_t可调类别权重。',
  '只比较调制因子，取γ=2、暂令α_t=1。简单样本p_t=0.99，交叉熵约0.01005，乘0.0001后约0.000001005；困难样本p_t=0.2，交叉熵约1.609，乘0.64后约1.030。大量简单背景的单项影响被显著压低，困难样本保留较大影响。'
 ]);
 deepen('free','FCOS的四边距离、中心度和多尺度分配',[
  'FCOS对一个负责位置预测到目标左、上、右、下边的距离 l、t、r、b。位置在框外时无法得到四个非负内部距离；同一位置落在多个真实框里时，又需要分配规则选择监督目标。多尺度范围等规则帮助处理这种歧义。',
  '中心度用于反映位置离目标中心有多近，原始形式为 \\(c=\\sqrt{\\frac{\\min(l,r)}{\\max(l,r)}\\frac{\\min(t,b)}{\\max(t,b)}}\\)。当两边距离平衡时接近1；靠边时一侧距离很短，分数会降低。它给分类分数增加与位置质量相关的线索。',
  '例如(l,t,r,b)=(20,10,30,40)，中心度为 sqrt((20/30)×(10/40))≈0.408；若改为(25,25,25,25)，得到1。距离预测仍需定位损失训练，中心度并不能代替准确的框回归。',
  'Anchor-based与Anchor-free的共同工作仍包括提特征、组织候选、分配目标、计算损失和筛选结果。前者以预设宽高为参考，后者可使用点到边等表示。比较时应具体检查哪部分简化了、哪部分转移到分配或参数化中了。'
 ]);
 deepen('2020','为什么工程流程也改变了检测器的使用方式',[
  '实际项目面对的是一整套数据流：标签规范、批次增强、模型构建、预训练加载、优化器、验证、保存和导出。网络图相同，若类别顺序写错、增强后框没同步、验证泄漏，实验结果仍会失真。YOLOv5这类项目把这些环节放进相对完整的运行流程，降低了使用和复现实验的组织成本。',
  '用本课的两类640输入计算标准YOLOv5 v7.0输出：80×80、40×40、20×20三张图，每处3个Anchor，每条有4个框参数、1个物体性和2个类别字段。候选数为3×(6400+1600+400)=25200，每候选7个数；最终几处对象要在后处理之后确定。',
  'Mosaic把多张图放进一个训练画布，增加尺寸和上下文变化；所有框也要按缩放、平移、裁切同步变换。推理不需要把新图片强行拼成Mosaic。区分训练输入构造与部署输入处理，是理解这些工程改进的前提。',
  '比较版本时，应把主干和预测头的改动、训练策略、输入尺度及部署方式分别列出。同一设备上的单张延迟与大批量吞吐率也不同；只看论文中的FPS数字，容易把不同计算条件混在一起。'
 ]);
 deepen('detr','一对一匹配究竟怎样抑制重复预测',[
  '原始DETR通常先用CNN提取特征，将空间位置展开为特征序列并加入位置信息。Transformer让这些位置交换信息，再由查询从图像特征中读取与对象相关的内容，预测类别和归一化框。位置编码使网络能区分相同视觉线索位于图像的哪里。',
  '匹配代价综合类别和定位等因素。用两目标A/B、两预测1/2的教学代价矩阵举例：预测1对A为1、对B为2；预测2对A为1.1、对B为100。如果先贪心把1配A，剩下2只能配B，总代价101；全局匹配选择1配B、2配A，总代价3.1。匈牙利算法求的是整体配对，而非每个目标各自独立挑一个预测。',
  '匹配完成后，损失再监督每个预测的类别以及匹配对象的框；未匹配预测学习无对象。这是每次训练依据当前预测重新计算的分配，不是把某个查询永久指定给图中的某一辆车。',
  '原始框损失结合中心宽高坐标的L1项与广义IoU项，前者直接度量坐标差，后者考虑几何重叠关系。全局匹配和一对一监督为直接集合输出提供条件；仍需看分类置信度筛出有效对象，输出固定槽位不等于每个槽位都代表真实目标。'
 ],{headers:['教学匹配代价','目标A','目标B'],rows:[['预测1','1','2'],['预测2','1.1','100'],['全局最小配对','预测2→A','预测1→B'] ]});
 deepen('2021','注意力采样、解耦头和动态分配各改哪一处',[
  '全局注意力需要处理位置间关系。用数量级例子，40×40特征有1600个位置，完整位置对关系约256万；80×80有6400个位置，约4096万。这里展示的是关系数量的平方增长，不是完整模型的显存或耗时测量。高分辨率能帮助定位，也使直接密集交互更贵。',
  'Deformable DETR根据参考位置和学习到的偏移，在多尺度特征中只采样少量相关点，并学习怎样加权组合。它改变了读取图像信息的方式，保留端到端集合预测的思路；具体采样位置、层级和权重均参与训练。',
  'YOLOX的解耦头让分类与定位有各自的特征处理分支。分类更关注对象种类，定位还要精细几何信息；分开处理为两项任务提供了不同的参数路径，最终输出和损失仍需明确衔接。',
  'SimOTA不是简单按固定IoU门槛选所有正样本。它结合候选范围、预测分类与重叠等代价，通过动态数量的匹配安排负责预测，之后再由损失监督。预测表示、分支结构、训练分配是三处不同改动，应该分别分析各自作用。'
 ]);
 deepen('2023','文字怎样进入检测，以及实时究竟测了什么',[
  '固定类别检测通常为每个预定类别学习输出通道；语言条件检测则把文字编码成特征，与图像特征在网络中融合，预测区域与文字表达的对应关系。Grounding DINO中的语言引导查询选择和跨模态解码，让查询能够使用输入文字来定位。',
  '给出“左侧红色汽车”时，模型需要处理类别、属性和空间关系。给出“车辆”与“汽车”的结果也可能不同；评价开放词汇能力时，应明确训练见过哪些类别、测试哪些新类别、提示怎样写，以及使用何种标注和阈值。',
  'RT-DETR围绕实时集合检测设计高效编码器，并选择较合适的特征作为初始查询。主干、特征交互、查询数量和解码层数共同影响速度；少一个传统后处理步骤有价值，但并不意味着其他网络计算为零。',
  '从用户点开摄像头到看到框，时间还包括解码视频、缩放、传输、模型和画图。报告模型推理时间与报告整套系统延迟应分别说明；比较时还要统一硬件、精度、输入和批次。否则所谓“实时”可能对应完全不同的运行条件。'
 ]);
 deepen('2024','双重分配如何把训练密度与最终输出联系起来',[
  '密集的一对多分配可让多个预测从同一真实目标获得训练信号，但推理可能出现重复框；一对一分配更接近每个对象一个输出，却需要确保训练信号和优化充分。YOLOv10围绕两种分配的一致性设计训练，使训练中的丰富监督与推理中的免NMS输出能够衔接。',
  '因此，给现有YOLOv5删掉NMS并不能得到YOLOv10式检测器。YOLOv5原有监督与候选组织允许多个位置预测同一对象，直接输出会保留许多重复框。修改后处理依赖时，需要回看训练分配、预测分支和评分的共同约定。',
  '这个例子也说明如何读后续论文：把贡献拆成可定位的计算或训练改动，检查作者怎样做消融，再看精度、延迟、内存是否在同一评价条件下改善。年份与模型名用于查资料，设计机制和实验证据才说明它适合解决什么问题。'
 ]);
 deepen('connect','把同一个漏检问题，放回整条技术史里判断',[
  '设远处行人在原图里只有16像素高，缩放后仅剩8像素。首先检查图片和标注、缩放比例及负责尺度，判断目标还有多少输入信息；此时只换分类损失，未必能弥补空间细节的损失。历史上的多尺度搜索、SSD、FPN和小目标预测分支，都与尺度问题相关，但各自的成本和机制不同。',
  '若模型已经给出正确候选，只是分数阈值或NMS将它删掉，就该先看后处理。若低光照图片根本缺少有效特征，应看数据覆盖、增强和表征。若大量简单背景主导训练，则可检查采样、分配和损失。先确定失败在哪一步，再选择技术，比只按新旧替换模块更容易解释结果。',
  '做一张自己的阅读表：每种方法分别填写搜索位置、视觉特征、框表示、监督分配、重复结果处理、主要成本。写不清的一栏就是需要补读的知识点。这样，发展史会成为读源码和设计实验时可用的索引。'
 ]);
 l.time=120;
 catalog.splice(catalog.findIndex(x=>x.group==='yolo'),0,l);curriculum.lessons.unshift(l);curriculum.phases[0].ids.unshift(l.id);
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const old=window.visionlabYoloLearning.renderParagraph.bind(window.visionlabYoloLearning);
 window.visionlabYoloLearning.renderParagraph=(s,i)=>{
  let html=old(s,i);if(!s.historyRefs)return html;
  if(s.id==='history-start'&&i===0)html+='<figure class="yd-workshop yl-figure"><figcaption><strong>一张路口图，贯穿整个问题</strong></figcaption><svg viewBox="0 0 640 180" role="img" aria-label="路口上两辆车和一个行人，每个对象都有独立矩形框"><rect width="640" height="180" fill="#eff3ef"/><path d="M0 118H640" stroke="#d1d8dc" stroke-width="72"/><g fill="#719b8a"><rect x="90" y="96" width="100" height="40" rx="8"/><rect x="380" y="98" width="115" height="40" rx="8"/></g><g fill="#637f9d"><circle cx="285" cy="78" r="10"/><path d="M285 90V126M285 100L266 115M285 100L304 115M285 126L271 150M285 126L299 150" stroke="#637f9d" stroke-width="6"/></g><g fill="none" stroke="#7660a6" stroke-width="2"><rect x="80" y="87" width="120" height="60"/><rect x="370" y="89" width="135" height="60"/><rect x="256" y="62" width="58" height="96"/></g><g fill="#35445a" font-size="16"><text x="80" y="76">车 A</text><text x="370" y="78">车 B</text><text x="256" y="50">行人</text></g></svg><p>目标始终是分别找出对象；历史中的方法改变的是如何搜索、表示、学习和筛选。</p><details><summary>展开全课时间线，跳到感兴趣的年代</summary><ol>'+parts.slice(0,-1).map(p=>`<li><a href="#section-${p.id}">${esc(p.title.replace(/^\d+\. /,''))}</a></li>`).join('')+'</ol></details></figure>';
  if(i===0)html+='<figure class="yd-workshop yl-figure"><figcaption><strong>这一阶段怎样处理图片</strong></figcaption><ol class="yl-flow">'+s.historyFlow.map((x,n)=>`<li><span>${n+1}</span><b>${esc(x)}</b></li>`).join('')+'</ol></figure>';
  if(s.historyTable&&i===s.historyTableAt)html+='<figure class="yd-workshop yl-figure"><figcaption><strong>跟着数字算一遍</strong></figcaption><div style="overflow-x:auto"><table><thead><tr>'+s.historyTable.headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+s.historyTable.rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>计算条件与符号含义见本节正文。</p></figure>';
  if(i===s.paragraphs.length-1)html+='<p class="source-note">本节原始资料：'+s.historyRefs.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)} ↗</a>`).join(' · ')+'</p>';
  return html;
 };
})();
